   197→	column: i32
   198→}
   199→
   200→// Parser 생성
   201→fn new_parser(tokens: []Token) Parser {
   202→	return Parser{
   203→		tokens: tokens,
   204→		pos: 0,
   205→		errors: []
   206→	}
   207→}
   208→
   209→// 현재 토큰 반환
   210→fn (mut p: Parser) current() Token {
   211→	if p.pos >= p.tokens.len() {
   212→		return Token{type_val: 99, text: "EOF", line: 0, column: 0}
   213→	}
   214→	return p.tokens[p.pos]
   215→}
   216→
   217→// 다음 토큰 반환
   218→fn (mut p: Parser) peek() Token {
   219→	if p.pos + 1 >= p.tokens.len() {
   220→		return Token{type_val: 99, text: "EOF", line: 0, column: 0}
   221→	}
   222→	return p.tokens[p.pos + 1]
   223→}
   224→
   225→// 토큰 타입 확인
   226→fn (mut p: Parser) check(token_type: i32) bool {
   227→	return p.current().type_val == token_type
   228→}
   229→
   230→// 토큰 타입 일치 및 이동
   231→fn (mut p: Parser) match(token_type: i32) bool {
   232→	if p.check(token_type) {
   233→		p.pos += 1
   234→		return true
   235→	}
   236→	return false
   237→}
   238→
   239→// 파일 끝 확인
   240→fn (mut p: Parser) is_at_end() bool {
   241→	return p.pos >= p.tokens.len() || p.check(99) // 99 = EOF
   242→}
   243→
   244→// 에러 추가
   245→fn (mut p: Parser) add_error(message: string) {
   246→	p.errors.push(message)
   247→}
   248→
   249→// 주요 Parse 함수
   250→fn (mut p: Parser) parse() ?Program {
   251→	mut definitions: []Definition = []
   252→	mut main_body: []Statement = []
   253→
   254→	for !p.is_at_end() {
   255→		if p.check(99) { // EOF
   256→			break
   257→		}
   258→
   259→		// fn 키워드: 함수 정의
   260→		if p.check(1) { // TknFn = 1
   261→			if let Some(def) = p.parse_function_def() {
   262→				definitions.push(def)
   263→			}
   264→		}
   265→		// type 키워드: 타입 정의
   266→		else if p.check(2) { // TknType = 2
   267→			if let Some(def) = p.parse_type_def() {
   268→				definitions.push(def)
   269→			}
   270→		}
   271→		// struct 키워드: 구조체 정의
   272→		else if p.check(3) { // TknStruct = 3
   273→			if let Some(def) = p.parse_struct_def() {
   274→				definitions.push(def)
   275→			}
   276→		}
   277→		// interface 키워드: 인터페이스 정의
   278→		else if p.check(4) { // TknInterface = 4
   279→			if let Some(def) = p.parse_interface_def() {
   280→				definitions.push(def)
   281→			}
   282→		}
   283→		// enum 키워드: enum 정의
   284→		else if p.check(5) { // TknEnum = 5
   285→			if let Some(def) = p.parse_enum_def() {
   286→				definitions.push(def)
   287→			}
   288→		}
   289→		// 그 외: 일반 statement
   290→		else {
   291→			if let Some(stmt) = p.parse_statement() {
   292→				main_body.push(stmt)
   293→			}
   294→		}
   295→	}
   296→
   297→	return Program{
   298→		definitions: definitions,
   299→		main_body: main_body
   300→	}
   301→}
   302→
   303→// 함수 정의 파싱
   304→fn (mut p: Parser) parse_function_def() ?FunctionDef {
   305→	if !p.match(1) { // TknFn
   306→		return none
   307→	}
   308→
   309→	// 함수 이름
   310→	name := p.current().text
   311→	if !p.match(10) { // TknIdentifier
   312→		p.add_error("expected function name")
   313→		return none
   314→	}
   315→
   316→	// ( 확인
   317→	if !p.match(12) { // TknLParen
   318→		p.add_error("expected '('")
   319→		return none
   320→	}
   321→
   322→	// 파라미터 파싱
   323→	mut parameters: []Parameter = []
   324→	if !p.check(13) { // TknRParen
   325→		for {
   326→			param_name := p.current().text
   327→			if !p.match(10) { // TknIdentifier
   328→				p.add_error("expected parameter name")
   329→				return none
   330→			}
   331→
   332→			// : Type
   333→			if !p.match(30) { // TknColon
   334→				p.add_error("expected ':' in parameter")
   335→				return none
   336→			}
   337→
   338→			param_type := p.parse_type() or {
   339→				p.add_error("expected type")
   340→				return none
   341→			}
   342→
   343→			parameters.push(Parameter{
   344→				name: param_name,
   345→				type_info: param_type
   346→			})
   347→
   348→			if !p.check(14) { // TknComma
   349→				break
   350→			}
   351→			p.pos += 1 // skip comma
   352→		}
   353→	}
   354→
   355→	// ) 확인
   356→	if !p.match(13) { // TknRParen
   357→		p.add_error("expected ')'")
   358→		return none
   359→	}
   360→
   361→	// 반환 타입 파싱 (-> Type)
   362→	mut return_type: ?Type = none
   363→	if p.match(31) { // TknArrow
   364→		return_type = p.parse_type()
   365→	}
   366→
   367→	// { 확인
   368→	if !p.match(14) { // TknLBrace
   369→		p.add_error("expected '{'")
   370→		return none
   371→	}
   372→
   373→	// 함수 본문 파싱
   374→	mut body: []Statement = []
   375→	if !p.check(15) { // TknRBrace
   376→		for {
   377→			if let Some(stmt) = p.parse_statement() {
   378→				body.push(stmt)
   379→			}
   380→			if p.check(15) || p.is_at_end() {
   381→				break
   382→			}
   383→		}
   384→	}
   385→
   386→	// } 확인
   387→	if !p.match(15) { // TknRBrace
   388→		p.add_error("expected '}'")
   389→		return none
   390→	}
   391→
   392→	return FunctionDef{
   393→		name: name,
   394→		parameters: parameters,
   395→		return_type: return_type,
   396→		body: body
   397→	}
   398→}
