   400→// 타입 정의 파싱
   401→fn (mut p: Parser) parse_type_def() ?TypeDef {
   402→	if !p.match(2) { // TknType
   403→		return none
   404→	}
   405→
   406→	name := p.current().text
   407→	if !p.match(10) { // TknIdentifier
   408→		p.add_error("expected type name")
   409→		return none
   410→	}
   411→
   412→	// { 확인
   413→	if !p.match(14) { // TknLBrace
   414→		p.add_error("expected '{'")
   415→		return none
   416→	}
   417→
   418→	// 필드 파싱
   419→	mut fields: []Field = []
   420→	if !p.check(15) { // TknRBrace
   421→		for {
   422→			if let Some(field) = p.parse_field() {
   423→				fields.push(field)
   424→			}
   425→			if p.check(15) || p.is_at_end() {
   426→				break
   427→			}
   428→		}
   429→	}
   430→
   431→	// } 확인
   432→	if !p.match(15) { // TknRBrace
   433→		p.add_error("expected '}'")
   434→		return none
   435→	}
   436→
   437→	return TypeDef{
   438→		name: name,
   439→		fields: fields
   440→	}
   441→}
