   443→// 구조체 정의 파싱
   444→fn (mut p: Parser) parse_struct_def() ?StructDef {
   445→	if !p.match(3) { // TknStruct
   446→		return none
   447→	}
   448→
   449→	name := p.current().text
   450→	if !p.match(10) { // TknIdentifier
   451→		p.add_error("expected struct name")
   452→		return none
   453→	}
   454→
   455→	// { 확인
   456→	if !p.match(14) { // TknLBrace
