   464→		for {
   465→			if let Some(field) = p.parse_field() {
   466→				fields.push(field)
   467→			}
   468→			if p.check(15) || p.is_at_end() {
   469→				break
   470→			}
   471→		}
   472→	}
   473→
   474→	// } 확인
   475→	if !p.match(15) { // TknRBrace
