   529→// enum 정의 파싱
   530→fn (mut p: Parser) parse_enum_def() ?EnumDef {
   531→	if !p.match(5) { // TknEnum
   532→		return none
   533→	}
   534→
   535→	name := p.current().text
   536→	if !p.match(10) { // TknIdentifier
   537→		p.add_error("expected enum name")
   538→		return none
   539→	}
   540→
   541→	// { 확인
   542→	if !p.match(14) { // TknLBrace
   543→		p.add_error("expected '{'")
   544→		return none
   545→	}
   546→
   547→	// variant 파싱
   548→	mut variants: []EnumVariant = []
   549→	if !p.check(15) { // TknRBrace
   550→		for {
   551→			variant_name := p.current().text
   552→			if !p.match(10) { // TknIdentifier
   553→				p.add_error("expected variant name")
   554→				return none
   555→			}
   556→
   557→			mut variant_types: []Type = []
   558→			// (Type1, Type2, ...) 형식
   559→			if p.match(12) { // TknLParen
   560→				if !p.check(13) { // TknRParen
   561→					for {
   562→						if let Some(vtype) = p.parse_type() {
   563→							variant_types.push(vtype)
   564→						}
   565→						if !p.check(14) { // TknComma
   566→							break
   567→						}
   568→						p.pos += 1 // skip comma
   569→					}
   570→				}
   571→				if !p.match(13) { // TknRParen
   572→					p.add_error("expected ')'")
   573→					return none
   574→				}
   575→			}
   576→
   577→			variants.push(EnumVariant{
   578→				name: variant_name,
   579→				types: variant_types
   580→			})
   581→
   582→			if p.check(14) { // TknComma
   583→				p.pos += 1
   584→			}
   585→			if p.check(15) || p.is_at_end() {
   586→				break
   587→			}
   588→		}
   589→	}
   590→
   591→	// } 확인
   592→	if !p.match(15) { // TknRBrace
   593→		p.add_error("expected '}'")
   594→		return none
   595→	}
   596→
   597→	return EnumDef{
   598→		name: name,
   599→		variants: variants
   600→	}
   601→}
   602→
   603→// 필드 파싱
   604→fn (mut p: Parser) parse_field() ?Field {
   605→	name := p.current().text
   606→	if !p.match(10) { // TknIdentifier
   607→		return none
   608→	}
   609→
   610→	// : Type
   611→	if !p.match(30) { // TknColon
   612→		p.add_error("expected ':' in field")
   613→		return none
   614→	}
   615→
   616→	field_type := p.parse_type() or {
   617→		p.add_error("expected type")
   618→		return none
   619→	}
   620→
   621→	// 기본값 (선택사항)
   622→	mut default_val: ?Expression = none
   623→	if p.match(32) { // TknAssign (=)
   624→		// 기본값 파싱
   625→		// default_val = p.parse_expression()
   626→	}
   627→
   628→	return Field{
   629→		name: name,
   630→		type_info: field_type,
   631→		mutable: false,
   632→		default_val: default_val
   633→	}
   634→}
