   636→// 메서드 시그니처 파싱
   637→fn (mut p: Parser) parse_method_sig() ?MethodSig {
   638→	name := p.current().text
   639→	if !p.match(10) { // TknIdentifier
   640→		return none
   641→	}
   642→
   643→	// ( 확인
   644→	if !p.match(12) { // TknLParen
   645→		p.add_error("expected '('")
   646→		return none
   647→	}
   648→
   649→	// 파라미터 파싱
   650→	mut parameters: []Parameter = []
   651→	if !p.check(13) { // TknRParen
   652→		for {
   653→			param_name := p.current().text
   654→			if !p.match(10) { // TknIdentifier
   655→				return none
   656→			}
   657→
   658→			if !p.match(30) { // TknColon
   659→				p.add_error("expected ':'")
   660→				return none
   661→			}
   662→
   663→			param_type := p.parse_type() or {
   664→				return none
   665→			}
   666→
   667→			parameters.push(Parameter{
   668→				name: param_name,
   669→				type_info: param_type
   670→			})
   671→
   672→			if !p.check(14) { // TknComma
   673→				break
   674→			}
   675→			p.pos += 1
   676→		}
   677→	}
   678→
   679→	// ) 확인
   680→	if !p.match(13) { // TknRParen
   681→		p.add_error("expected ')'")
   682→		return none
   683→	}
   684→
   685→	// 반환 타입 파싱
   686→	mut return_type: ?Type = none
   687→	if p.match(31) { // TknArrow
   688→		return_type = p.parse_type()
   689→	}
   690→
   691→	return MethodSig{
