   698→// Statement 파싱
   699→fn (mut p: Parser) parse_statement() ?Statement {
   700→	// let 바인딩
   701→	if p.check(6) { // TknLet
   702→		return p.parse_let_statement()
   703→	}
   704→	// const 바인딩
   705→	else if p.check(7) { // TknConst
   706→		return p.parse_const_statement()
   707→	}
   708→	// if 문
   709→	else if p.check(8) { // TknIf
   710→		return p.parse_if_statement()
   711→	}
   712→	// for 루프
   713→	else if p.check(9) { // TknFor
   714→		return p.parse_for_statement()
   715→	}
   716→	// match 식
   717→	else if p.check(11) { // TknMatch
   718→		return p.parse_match_statement()
   719→	}
   720→	// return 문
   721→	else if p.check(17) { // TknReturn
   722→		return p.parse_return_statement()
   723→	}
   724→	// 표현식 문장
   725→	else {
   726→		return p.parse_expression_statement()
   727→	}
   728→}
   729→
   730→// let 문 파싱
   731→fn (mut p: Parser) parse_let_statement() ?Statement {
   732→	if !p.match(6) { // TknLet
   733→		return none
   734→	}
   735→
   736→	name := p.current().text
   737→	if !p.match(10) { // TknIdentifier
   738→		p.add_error("expected variable name")
   739→		return none
   740→	}
   741→
   742→	// 타입 (선택사항)
   743→	mut type_info: ?Type = none
   744→	if p.match(30) { // TknColon
   745→		type_info = p.parse_type()
   746→	}
   747→
   748→	// = 확인
   749→	if !p.match(32) { // TknAssign
   750→		p.add_error("expected '=' in let binding")
   751→		return none
   752→	}
   753→
   754→	// 초기값
   755→	let init = p.parse_expression() or {
   756→		p.add_error("expected expression")
   757→		return none
   758→	}
   759→
   760→	return LetStatement{
   761→		name: name,
   762→		type_info: type_info,
   763→		init: init,
   764→		mutable: false
   765→	}
   766→}
   767→
   768→// const 문 파싱
   769→fn (mut p: Parser) parse_const_statement() ?Statement {
   770→	if !p.match(7) { // TknConst
   771→		return none
   772→	}
   773→
   774→	name := p.current().text
   775→	if !p.match(10) { // TknIdentifier
   776→		p.add_error("expected constant name")
   777→		return none
   778→	}
   779→
   780→	// 타입 (선택사항)
   781→	mut type_info: ?Type = none
   782→	if p.match(30) { // TknColon
   783→		type_info = p.parse_type()
   784→	}
   785→
   786→	// = 확인
   787→	if !p.match(32) { // TknAssign
   788→		p.add_error("expected '='")
   789→		return none
   790→	}
   791→
   792→	// 값
   793→	let value = p.parse_expression() or {
   794→		p.add_error("expected expression")
   795→		return none
   796→	}
   797→
   798→	return ConstStatement{
   799→		name: name,
   800→		type_info: type_info,
   801→		value: value
   802→	}
   803→}
   804→
   805→// if 문 파싱
   806→fn (mut p: Parser) parse_if_statement() ?Statement {
   807→	if !p.match(8) { // TknIf
   808→		return none
   809→	}
   810→
   811→	// 조건
   812→	let condition = p.parse_expression() or {
   813→		p.add_error("expected condition")
   814→		return none
   815→	}
   816→
   817→	// { 확인
   818→	if !p.match(14) { // TknLBrace
   819→		p.add_error("expected '{'")
   820→		return none
   821→	}
   822→
   823→	// then body
   824→	mut then_body: []Statement = []
   825→	if !p.check(15) { // TknRBrace
   826→		for {
   827→			if let Some(stmt) = p.parse_statement() {
   828→				then_body.push(stmt)
   829→			}
   830→			if p.check(15) || p.is_at_end() {
   831→				break
   832→			}
   833→		}
   834→	}
   835→
   836→	// } 확인
   837→	if !p.match(15) { // TknRBrace
   838→		p.add_error("expected '}'")
   839→		return none
   840→	}
   841→
   842→	// else body (선택사항)
   843→	mut else_body: []Statement = []
   844→	if p.match(18) { // TknElse
   845→		// else if 또는 else { }
   846→		if p.check(8) { // TknIf
   847→			if let Some(else_if_stmt) = p.parse_if_statement() {
   848→				else_body.push(else_if_stmt)
   849→			}
   850→		} else if p.match(14) { // TknLBrace
   851→			if !p.check(15) { // TknRBrace
   852→				for {
   853→					if let Some(stmt) = p.parse_statement() {
   854→						else_body.push(stmt)
   855→					}
   856→					if p.check(15) || p.is_at_end() {
   857→						break
   858→					}
   859→				}
   860→			}
   861→			if !p.match(15) { // TknRBrace
   862→				p.add_error("expected '}'")
   863→				return none
   864→			}
   865→		}
   866→	}
   867→
   868→	return IfStatement{
   869→		condition: condition,
   870→		then_body: then_body,
   871→		else_body: else_body
   872→	}
   873→}
   874→
   875→// for 루프 파싱
   876→fn (mut p: Parser) parse_for_statement() ?Statement {
   877→	if !p.match(9) { // TknFor
   878→		return none
   879→	}
   880→
   881→	variable := p.current().text
   882→	if !p.match(10) { // TknIdentifier
   883→		p.add_error("expected variable name")
   884→		return none
   885→	}
   886→
   887→	// in 확인
   888→	if !p.match(19) { // TknIn
   889→		p.add_error("expected 'in'")
   890→		return none
   891→	}
   892→
   893→	// iterator 파싱
   894→	let iterator = p.parse_expression() or {
   895→		p.add_error("expected iterator")
   896→		return none
   897→	}
   898→
   899→	// { 확인
   900→	if !p.match(14) { // TknLBrace
   901→		p.add_error("expected '{'")
   902→		return none
   903→	}
   904→
   905→	// 본문
   906→	mut body: []Statement = []
   907→	if !p.check(15) { // TknRBrace
   908→		for {
   909→			if let Some(stmt) = p.parse_statement() {
   910→				body.push(stmt)
   911→			}
   912→			if p.check(15) || p.is_at_end() {
   913→				break
   914→			}
   915→		}
   916→	}
   917→
   918→	// } 확인
   919→	if !p.match(15) { // TknRBrace
   920→		p.add_error("expected '}'")
   921→		return none
   922→	}
   923→
   924→	return ForStatement{
   925→		variable: variable,
   926→		iterator: iterator,
   927→		body: body
   928→	}
   929→}
   930→
   931→// match 문 파싱
   932→fn (mut p: Parser) parse_match_statement() ?Statement {
   933→	if !p.match(11) { // TknMatch
   934→		return none
   935→	}
   936→
   937→	// 표현식
   938→	let expr = p.parse_expression() or {
   939→		p.add_error("expected expression")
   940→		return none
   941→	}
   942→
   943→	// { 확인
   944→	if !p.match(14) { // TknLBrace
   945→		p.add_error("expected '{'")
   946→		return none
   947→	}
   948→
   949→	// arms
   950→	mut arms: []MatchArm = []
   951→	if !p.check(15) { // TknRBrace
   952→		for {
   953→			// 패턴 파싱
   954→			// let pattern = p.parse_pattern() or { break }
   955→			// => 확인
   956→			if !p.match(31) { // TknArrow
   957→				break
   958→			}
   959→
   960→			// 바디
   961→			mut arm_body: []Statement = []
   962→			// ... 바디 파싱
   963→			break
   964→		}
   965→	}
   966→
   967→	// } 확인
   968→	if !p.match(15) { // TknRBrace
   969→		p.add_error("expected '}'")
   970→		return none
   971→	}
   972→
   973→	return MatchStatement{
   974→		expression: expr,
   975→		arms: arms
   976→	}
   977→}
   978→
   979→// return 문 파싱
   980→fn (mut p: Parser) parse_return_statement() ?Statement {
   981→	if !p.match(17) { // TknReturn
   982→		return none
   983→	}
   984→
   985→	// 값 (선택사항)
   986→	mut value: ?Expression = none
   987→	if !p.check(15) && !p.check(99) { // TknRBrace or EOF
   988→		value = p.parse_expression()
   989→	}
