   991→	return ReturnStatement{
   992→		value: value
   993→	}
   994→}
   995→
   996→// 표현식 문장
   997→fn (mut p: Parser) parse_expression_statement() ?Statement {
   998→	let expr = p.parse_expression() or {
   999→		return none
  1000→	}
  1001→	return ExpressionStatement{
  1002→		expression: expr
  1003→	}
  1004→}
  1005→
  1006→// Expression 파싱 (스텁)
  1007→fn (mut p: Parser) parse_expression() ?Expression {
  1008→	// 구현 필요 (별도 모듈)
  1009→	return none
  1010→}
  1011→
  1012→// Type 파싱
  1013→fn (mut p: Parser) parse_type() ?Type {
