import { execSync, spawnSync, execFileSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

/**
 * FVBridge: PyFree CLI에서 FV 2.0 Go 컴파일러를 호출하는 브릿지
 *
 * FV 소스 파일 (.fv)을 다음과 같이 처리:
 * - compile: .fv → C 코드 (stdout)
 * - build: .fv → 바이너리 (C → gcc)
 * - run: .fv → 즉시 실행 (build + exec)
 */
export class FVBridge {
  private fv2Binary: string;

  constructor(binaryPath?: string) {
    this.fv2Binary = binaryPath || this.findFV2Binary();
  }

  /**
   * FV2 바이너리 자동 탐색
   * 순서:
   * 1. FV2_PATH 환경변수
   * 2. PATH에서 fv2 찾기
   * 3. 기본 경로: ~/projects/fv2-lang-go/bin/fv2
   */
  private findFV2Binary(): string {
    // 1. 환경 변수 확인
    if (process.env.FV2_PATH) {
      const envPath = process.env.FV2_PATH;
      if (fs.existsSync(envPath)) {
        return envPath;
      }
      console.warn(`⚠️  FV2_PATH="${envPath}" does not exist`);
    }

    // 2. PATH에서 찾기
    try {
      const pathResult = execSync('which fv2', { encoding: 'utf-8' }).trim();
      if (pathResult) {
        return pathResult;
      }
    } catch {
      // fv2가 PATH에 없음
    }

    // 3. 기본 경로
    const homeDir = os.homedir();
    const defaultPath = path.join(homeDir, 'projects', 'fv2-lang-go', 'bin', 'fv2');
    if (fs.existsSync(defaultPath)) {
      return defaultPath;
    }

    throw new Error(
      `❌ FV2 compiler binary not found.\n\n` +
      `Please set FV2_PATH or ensure "fv2" is in PATH.\n` +
      `Expected default location: ${defaultPath}`
    );
  }

  /**
   * FV 소스 파일 → C 코드 생성
   *
   * @param fvFile FV 소스 파일 경로
   * @returns 생성된 C 코드 (문자열)
   */
  compile(fvFile: string): string {
    if (!fs.existsSync(fvFile)) {
      throw new Error(`❌ File not found: ${fvFile}`);
    }

    try {
      const cCode = execSync(`${this.fv2Binary} ${fvFile}`, {
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'], // 에러도 捕捉
      });
      return cCode;
    } catch (error: any) {
      throw new Error(
        `❌ FV compilation failed:\n${error.stderr || error.message}`
      );
    }
  }

  /**
   * FV 소스 파일 → 바이너리 빌드
   *
   * 단계:
   * 1. compile() → C 코드
   * 2. 임시 .c 파일에 저장
   * 3. gcc로 바이너리 컴파일
   * 4. 임시 .c 파일 삭제
   *
   * @param fvFile FV 소스 파일 경로
   * @param outFile 출력 바이너리 경로
   */
  build(fvFile: string, outFile?: string): void {
    // gcc 존재 여부 확인
    if (!this.checkGCC()) {
      throw new Error(
        `❌ gcc/clang not found. Required for building .fv files.\n` +
        `   Install with: apt-get install build-essential (Debian/Ubuntu) or\n` +
        `                 brew install gcc (macOS) or\n` +
        `                 pkg install clang (Termux)`
      );
    }

    const output = outFile || 'a.out';

    try {
      // Step 1: C 코드 생성
      console.log(`🔧 Compiling ${path.basename(fvFile)} to C...`);
      const cCode = this.compile(fvFile);

      // Step 2: 임시 C 파일 생성
      const timestamp = Date.now();
      const cFile = path.join(os.tmpdir(), `fv_build_${timestamp}.c`);
      fs.writeFileSync(cFile, cCode);

      // Step 3: gcc로 빌드
      console.log(`🏗️  Building binary: ${output}`);
      try {
        execSync(`gcc -o ${output} ${cFile}`, { stdio: 'inherit' });
      } catch (error) {
        fs.unlinkSync(cFile); // 임시 파일 정리
        throw error;
      }

      // Step 4: 임시 C 파일 정리
      fs.unlinkSync(cFile);

      console.log(`✅ Build successful: ${output}`);
    } catch (error: any) {
      throw new Error(`❌ Build failed: ${error.message}`);
    }
  }

  /**
   * FV 소스 파일 → 즉시 실행
   *
   * 단계:
   * 1. build() → 임시 바이너리
   * 2. spawnSync()로 실행
   * 3. 임시 바이너리 정리
   *
   * @param fvFile FV 소스 파일 경로
   */
  run(fvFile: string): void {
    const timestamp = Date.now();
    const tempBinary = path.join(os.tmpdir(), `fv_run_${timestamp}`);

    try {
      // Step 1: 임시 바이너리로 빌드
      this.build(fvFile, tempBinary);

      // Step 2: 실행
      console.log(`\n📍 Running ${path.basename(fvFile)}...\n`);
      spawnSync(tempBinary, [], { stdio: 'inherit' });

      // Step 3: 정리
      if (fs.existsSync(tempBinary)) {
        fs.unlinkSync(tempBinary);
      }
    } catch (error) {
      // 임시 파일 정리
      if (fs.existsSync(tempBinary)) {
        try {
          fs.unlinkSync(tempBinary);
        } catch {
          // 무시
        }
      }
      throw error;
    }
  }

  /**
   * gcc/clang 존재 여부 확인
   */
  private checkGCC(): boolean {
    try {
      execSync('gcc --version', { stdio: 'pipe' });
      return true;
    } catch {
      try {
        execSync('clang --version', { stdio: 'pipe' });
        return true;
      } catch {
        return false;
      }
    }
  }
}

